/**
 * `ledger setup` — the node half of the Windows installer (B7). `install.ps1` / `uninstall.ps1`
 * contain NO trust logic: every directory, ACL, generated file and digest decision is made here,
 * through platformTrust, so it is the same code the hub relies on and it is testable off Windows.
 *
 *   ledger setup --platform-init [--ledger-dir <abs>] [--data-dir <abs>] [--bin-dir <abs>] [--port <n>]
 *       verifies THIS node (trusted location, >= 22.18), creates the private directories
 *       (ledger, ledger/.hub, ledger/.hub/bin, data, bin), writes `hub.env` and the shims
 *       (ledger.cmd, ledger.ps1, ledger), prints ONE JSON line for the installer.
 *   ledger setup --private-dir <abs>          create one FRESH private directory (scratch space)
 *   ledger setup --place-gitleaks <exe> [--ledger-dir <abs>]
 *       copies an already verified gitleaks into `<ledger>/.hub/bin/` with its `.sha256` and
 *       `.origin` side-cars (what managedbin verifies before the hub ever executes it).
 *
 * Exit: 0 ok · 1 refused (trust / elevated / weak filesystem) · 4 validation.
 * No process is started here (I3); the pure renderers below are exported for the golden-file tests
 * and for `adapters/claude-code/install-hooks.mjs`.
 */

import { createHash, randomBytes } from 'node:crypto';
import { lstat, readFile, rename, rm } from 'node:fs/promises';
import os from 'node:os';
import nodePath from 'node:path';
import {
  assertShimSafePath,
  crtQuoteArgv,
  ensurePrivateDir,
  openPrivate,
  resolveTrustedExecutable,
  TrustError,
  type FsCaps,
  type TrustDeps,
} from '@agent-ledger/shared';
import { flag, type Args } from './args.ts';
import type { Io } from './index.ts';

export const TASK_NAME = 'agent-ledger';
/** Description the installer gives the scheduled task; uninstall only touches a task carrying it. */
export const TASK_DESCRIPTION = 'agent-ledger hub (started at logon by install.ps1)';
export const SHIM_MARKER = 'agent-ledger shim (generated by install.ps1)';
export const MIN_NODE: readonly [number, number] = [22, 18];
/** Same optional-feature flags install.sh passes into the service environment. */
export const PASSTHROUGH_VARS: readonly string[] = [
  'LEDGER_PUSH',
  'LEDGER_INTRUDE',
  'LEDGER_RECAP_GUARD',
  'LEDGER_RECAP_TAGS',
  'LEDGER_WEB_REPLIES',
  'LEDGER_AGENTS_DIR',
  'LEDGER_GROOM_WEEKLY',
];

// ---- pure renderers (golden-file tested) ------------------------------------------------

const NON_ASCII = /[^\u0020-\u007e]/;
const QUOTES_PS = /['\u2018\u2019\u201a\u201b]/g;

export interface ShimInput {
  /** Absolute node.exe. */
  node: string;
  /** Absolute `packages/cli/src/bin.ts`. */
  cliBin: string;
  longPaths?: boolean;
}

function checkShimInput(o: ShimInput): void {
  assertShimSafePath(o.node, { longPaths: o.longPaths === true });
  assertShimSafePath(o.cliBin, { longPaths: o.longPaths === true });
}

/**
 * `ledger.cmd`: CRLF, delayed expansion off, ONE exec line. Both paths already passed
 * `assertShimSafePath` (no `% ! "` or control characters), so quoting them is enough. A path with
 * non-ASCII characters is refused here (cmd.exe reads the file in the OEM code page and would
 * run a different path); the ps1 / sh shims still work for such a profile.
 */
export function renderCmdShim(o: ShimInput): string {
  checkShimInput(o);
  if (NON_ASCII.test(o.node) || NON_ASCII.test(o.cliBin)) {
    throw new RangeError('shim path: non-ASCII characters cannot be written safely into a .cmd file');
  }
  return [`@rem ${SHIM_MARKER}`, '@setlocal DisableDelayedExpansion', `@"${o.node}" "${o.cliBin}" %*`, ''].join('\r\n');
}

/** `ledger.ps1` (single-quoted literals; every PowerShell quote character is doubled). Written with a BOM by the caller. */
export function renderPs1Shim(o: ShimInput): string {
  checkShimInput(o);
  const q = (s: string): string => `'${s.replace(QUOTES_PS, (c) => c + c)}'`;
  return [
    `# ${SHIM_MARKER}`,
    `& ${q(o.node)} ${q(o.cliBin)} @args`,
    'exit $LASTEXITCODE',
    '',
  ].join('\r\n');
}

/** Windows path -> the form Git Bash passes through to a native exe unchanged (`C:/Program Files/...`). */
export function toSlashPath(p: string): string {
  return p.replace(/\\/g, '/');
}

/** `ledger` for Git Bash (LF, single-quoted). */
export function renderShShim(o: ShimInput): string {
  checkShimInput(o);
  const q = (s: string): string => `'${toSlashPath(s).replace(/'/g, `'\\''`)}'`;
  return ['#!/usr/bin/env bash', `# ${SHIM_MARKER}`, `exec ${q(o.node)} ${q(o.cliBin)} "$@"`, ''].join('\n');
}

const ENV_NAME_RE = /^[A-Z][A-Z0-9_]{0,63}$/;
// `#` starts a comment in an unquoted dotenv value and quotes/backtick change its parsing: refused, not escaped.
const ENV_VALUE_BAD = /[\u0000-\u001f\u007f"'`#]/;

/** `hub.env` for `node --env-file=`: `KEY=value` lines, values taken literally (no quoting, no escapes). */
export function renderHubEnv(entries: Readonly<Record<string, string>>): string {
  const lines: string[] = [];
  for (const [name, value] of Object.entries(entries)) {
    if (!ENV_NAME_RE.test(name)) throw new RangeError(`hub.env: bad variable name ${JSON.stringify(name)}`);
    if (typeof value !== 'string' || value === '' || value !== value.trim() || ENV_VALUE_BAD.test(value)) {
      throw new RangeError(`hub.env: value of ${name} is empty or contains a character that cannot be stored safely`);
    }
    lines.push(`${name}=${value}`);
  }
  return `${lines.join('\n')}\n`;
}

/** The scheduled task's argument string (parsed back by the CRT, so quoted with `crtQuoteArgv`). */
export function hubTaskArguments(o: { envFile: string; hubBin: string }): string {
  assertShimSafePath(o.envFile);
  assertShimSafePath(o.hubBin);
  return crtQuoteArgv([`--env-file=${o.envFile}`, '--disable-warning=ExperimentalWarning', o.hubBin]);
}

/**
 * Claude Code hook launcher for win32: node.exe + the script, never a `.cmd` shim (CVE-2024-27980
 * class, and `.cmd` needs a shell). The result is the `<launcher>` in `<launcher> hook <event>`;
 * Claude Code runs it through Git Bash or cmd, and forward slashes work in both. `$` and backtick
 * would be expanded inside bash double quotes, so they are refused like `% ! "`.
 */
export function winHookLauncher(o: ShimInput): string {
  checkShimInput(o);
  for (const p of [o.node, o.cliBin]) {
    if (/[$`]/.test(p)) throw new RangeError('hook path: contains "$" or a backtick');
  }
  return `"${toSlashPath(o.node)}" "${toSlashPath(o.cliBin)}"`;
}

/**
 * Launchers that previous `winHookLauncher` installs left in `settings` for this checkout's `bin.ts`
 * (`<launcher> hook <arg>` with `"<cliBin>"` as the last quoted word). Lets `--uninstall` find entries
 * even when node.exe has moved since the install.
 */
export function findWinHookLaunchers(settings: unknown, cliBin: string, hookArgs: readonly string[]): string[] {
  const found = new Set<string>();
  const tail = `"${toSlashPath(cliBin)}"`;
  const hooks = (settings as { hooks?: Record<string, unknown> } | null)?.hooks;
  if (hooks === null || typeof hooks !== 'object') return [];
  for (const blocks of Object.values(hooks)) {
    if (!Array.isArray(blocks)) continue;
    for (const block of blocks as Array<{ hooks?: Array<{ command?: unknown }> }>) {
      for (const entry of Array.isArray(block?.hooks) ? block.hooks : []) {
        const cmd = entry?.command;
        if (typeof cmd !== 'string' || !cmd.startsWith('"')) continue;
        for (const arg of hookArgs) {
          const suffix = ` hook ${arg}`;
          if (cmd.endsWith(`${tail}${suffix}`)) found.add(cmd.slice(0, cmd.length - suffix.length));
        }
      }
    }
  }
  return [...found];
}

export function nodeVersionOk(version: string): boolean {
  const m = /^v?(\d+)\.(\d+)\./.exec(version);
  if (m === null) return false;
  const major = Number(m[1]);
  const minor = Number(m[2]);
  return major > MIN_NODE[0] || (major === MIN_NODE[0] && minor >= MIN_NODE[1]);
}

// ---- path resolution --------------------------------------------------------------------

export interface SetupDeps {
  platform: NodeJS.Platform;
  execPath: string;
  nodeVersion: string;
  /** DI seam for platformTrust (tests pass fakes; production leaves it empty). */
  trust: Partial<TrustDeps>;
  homedir: () => string;
  /** Test seam: replaces the trusted-location check of node (returns a refusal reason, or null). */
  checkNode?: (execPath: string) => Promise<string | null>;
}

function pathApi(platform: NodeJS.Platform): typeof nodePath.posix {
  return platform === 'win32' ? nodePath.win32 : nodePath.posix;
}

function absolutePath(platform: NodeJS.Platform, what: string, p: string | undefined): string {
  const api = pathApi(platform);
  if (p === undefined || p === '' || p.includes('\0')) throw new RangeError(`${what}: empty`);
  const ok = platform === 'win32' ? /^[A-Za-z]:\\/.test(p) : api.isAbsolute(p);
  if (!ok) throw new RangeError(`${what}: must be an absolute ${platform === 'win32' ? 'drive-rooted ' : ''}path`);
  const norm = api.normalize(p).replace(/[\\/]+$/, '');
  if (norm === '' || (platform === 'win32' && /^[A-Za-z]:$/.test(norm))) throw new RangeError(`${what}: is a filesystem root`);
  return norm;
}

function under(api: typeof nodePath.posix, root: string, p: string): boolean {
  const rel = api.relative(root, p);
  return rel !== '' && !rel.startsWith('..') && !api.isAbsolute(rel);
}

interface Layout {
  ledgerDir: string;
  dataDir: string;
  binDir: string;
  hubEnv: string;
  hubBin: string;
  cliBin: string;
  port: number;
}

function resolveLayout(args: Args, env: NodeJS.ProcessEnv, d: SetupDeps): Layout {
  const api = pathApi(d.platform);
  const home = absolutePath(d.platform, 'home directory', d.homedir());
  const ledgerDir = absolutePath(d.platform, '--ledger-dir', flag(args, 'ledger-dir') ?? env.LEDGER_DIR?.trim() ?? api.join(home, '.ledger'));
  let dataDir = flag(args, 'data-dir');
  if (dataDir === undefined) {
    if (d.platform === 'win32') {
      // %LOCALAPPDATA% is only trusted when it is absolute and inside the profile; otherwise the standard place.
      const local = env.LOCALAPPDATA?.trim();
      const fallback = api.join(home, 'AppData', 'Local');
      let base = fallback;
      if (local !== undefined && /^[A-Za-z]:\\/.test(local)) {
        const n = absolutePath(d.platform, 'LOCALAPPDATA', local);
        if (under(api, home, n)) base = n;
      }
      dataDir = api.join(base, 'agent-ledger');
    } else {
      dataDir = api.join(home, '.local', 'share', 'agent-ledger');
    }
  }
  dataDir = absolutePath(d.platform, '--data-dir', dataDir);
  const binDir = absolutePath(d.platform, '--bin-dir', flag(args, 'bin-dir') ?? api.join(dataDir, 'bin'));
  const portRaw = flag(args, 'port') ?? env.LEDGER_HUB_PORT?.trim() ?? '4747';
  if (!/^\d{1,5}$/.test(portRaw) || Number(portRaw) < 1 || Number(portRaw) > 65535) {
    throw new RangeError(`invalid port ${JSON.stringify(portRaw)} (1..65535)`);
  }
  // This module lives at <repo>/packages/cli/src/setup.ts; the repo root is never taken from the command line.
  const repo = api.resolve(import.meta.dirname, '..', '..', '..');
  return {
    ledgerDir,
    dataDir,
    binDir,
    hubEnv: api.join(dataDir, 'hub.env'),
    hubBin: api.join(repo, 'packages', 'hub', 'src', 'bin.ts'),
    cliBin: api.join(repo, 'packages', 'cli', 'src', 'bin.ts'),
    port: Number(portRaw),
  };
}

// ---- file helpers -----------------------------------------------------------------------

async function writeAtomic(file: string, data: string | Uint8Array, mode: number, trust: Partial<TrustDeps>): Promise<void> {
  const tmp = `${file}.${randomBytes(6).toString('hex')}.tmp`;
  const h = await openPrivate(tmp, 'excl', mode, trust);
  try {
    await h.writeFile(data);
    await h.sync();
  } finally {
    await h.close();
  }
  try {
    await rename(tmp, file);
  } catch (err) {
    await rm(tmp, { force: true }).catch(() => undefined);
    throw err;
  }
}

/** Existing content of a file in a private directory, or null when absent. Symlinks / non-files refuse. */
async function readIfPresent(file: string, trust: Partial<TrustDeps>): Promise<string | null> {
  try {
    await lstat(file);
  } catch (err) {
    if ((err as { code?: string }).code === 'ENOENT') return null;
    throw err;
  }
  const h = await openPrivate(file, 'read', 0o600, trust);
  try {
    return await h.readText();
  } finally {
    await h.close();
  }
}

type ShimStatus = 'written' | 'unchanged' | 'left alone (not generated by install.ps1)' | `skipped: ${string}`;

async function placeShim(file: string, text: string, bom: boolean, mode: number, trust: Partial<TrustDeps>): Promise<ShimStatus> {
  const existing = await readIfPresent(file, trust);
  const data = bom ? `\ufeff${text}` : text;
  if (existing !== null) {
    if (!existing.includes(SHIM_MARKER)) return 'left alone (not generated by install.ps1)';
    if (existing === data) return 'unchanged';
  }
  await writeAtomic(file, data, mode, trust);
  return 'written';
}

function capsSummary(c: FsCaps): { fsType: string; weak: boolean; bypassed: boolean } {
  return { fsType: String(c.fsType), weak: c.weak === true, bypassed: c.bypassed === true };
}

// ---- modes ------------------------------------------------------------------------------

async function platformInit(args: Args, io: Io, d: SetupDeps): Promise<number> {
  if (!nodeVersionOk(d.nodeVersion)) {
    io.err(`ledger setup: node ${d.nodeVersion} is too old — type stripping needs >= ${MIN_NODE.join('.')}`);
    return 4;
  }
  // Refuses elevated on win32 (platformTrust) before anything is created.
  const reason =
    d.checkNode !== undefined
      ? await d.checkNode(d.execPath)
      : await nodeRefusal(d);
  if (reason !== null) {
    io.err(`ledger setup: node is not in a trusted location: ${reason}`);
    return 1;
  }
  const lay = resolveLayout(args, io.env, d);
  if (d.platform === 'win32') {
    for (const p of [d.execPath, lay.cliBin, lay.hubBin, lay.ledgerDir, lay.dataDir, lay.binDir, lay.hubEnv]) assertShimSafePath(p);
  }
  const api = pathApi(d.platform);
  const dirs = {
    dataDir: lay.dataDir,
    binDir: lay.binDir,
    ledgerDir: lay.ledgerDir,
    hubDir: api.join(lay.ledgerDir, '.hub'),
    hubBinDir: api.join(lay.ledgerDir, '.hub', 'bin'),
  };
  const fsInfo: Record<string, ReturnType<typeof capsSummary>> = {};
  for (const [name, dir] of Object.entries(dirs)) fsInfo[name] = capsSummary(await ensurePrivateDir(dir, d.trust));

  const envEntries: Record<string, string> = { LEDGER_DIR: lay.ledgerDir, LEDGER_HUB_PORT: String(lay.port) };
  for (const name of PASSTHROUGH_VARS) {
    const v = io.env[name];
    if (v !== undefined && v !== '') envEntries[name] = v;
  }
  await writeAtomic(lay.hubEnv, renderHubEnv(envEntries), 0o600, d.trust);

  const shimIn: ShimInput = { node: d.execPath, cliBin: lay.cliBin };
  const shims: Record<string, ShimStatus> = {};
  const attempt = async (key: string, file: string, render: () => string, bom: boolean, mode: number): Promise<void> => {
    let text: string;
    try {
      text = render();
    } catch (err) {
      if (err instanceof RangeError) {
        shims[key] = `skipped: ${err.message}`;
        return;
      }
      throw err;
    }
    shims[key] = await placeShim(file, text, bom, mode, d.trust);
  };
  await attempt('cmd', api.join(lay.binDir, 'ledger.cmd'), () => renderCmdShim(shimIn), false, 0o600);
  await attempt('ps1', api.join(lay.binDir, 'ledger.ps1'), () => renderPs1Shim(shimIn), true, 0o600);
  await attempt('sh', api.join(lay.binDir, 'ledger'), () => renderShShim(shimIn), false, 0o700);
  if (shims.cmd?.startsWith('skipped') === true && shims.ps1?.startsWith('skipped') === true) {
    io.err('ledger setup: no usable shim could be generated for these paths');
    return 4;
  }

  io.out(
    JSON.stringify({
      ok: true,
      platform: d.platform,
      node: d.execPath,
      nodeVersion: d.nodeVersion,
      ledgerDir: lay.ledgerDir,
      dataDir: lay.dataDir,
      binDir: lay.binDir,
      hubEnv: lay.hubEnv,
      hubBin: lay.hubBin,
      cliBin: lay.cliBin,
      port: lay.port,
      taskArguments: hubTaskArguments({ envFile: lay.hubEnv, hubBin: lay.hubBin }),
      shims,
      fs: fsInfo,
    }),
  );
  return 0;
}

async function nodeRefusal(d: SetupDeps): Promise<string | null> {
  const r = await resolveTrustedExecutable([d.execPath], {}, d.trust);
  if (r.path !== null) return null;
  return r.rejected[0] ?? 'not found';
}

async function privateDirMode(args: Args, io: Io, d: SetupDeps): Promise<number> {
  const dir = absolutePath(d.platform, '--private-dir', flag(args, 'private-dir'));
  if (d.platform === 'win32') assertShimSafePath(dir);
  try {
    await lstat(dir);
    io.err('ledger setup: --private-dir must not exist yet');
    return 1;
  } catch (err) {
    if ((err as { code?: string }).code !== 'ENOENT') throw err;
  }
  await ensurePrivateDir(dir, d.trust);
  io.out(dir);
  return 0;
}

const MAX_BINARY_BYTES = 256 * 1024 * 1024;

async function placeGitleaks(args: Args, io: Io, d: SetupDeps): Promise<number> {
  const api = pathApi(d.platform);
  const src = absolutePath(d.platform, '--place-gitleaks', flag(args, 'place-gitleaks'));
  const ledgerDir = absolutePath(
    d.platform,
    '--ledger-dir',
    flag(args, 'ledger-dir') ?? io.env.LEDGER_DIR?.trim() ?? api.join(absolutePath(d.platform, 'home directory', d.homedir()), '.ledger'),
  );
  const st = await lstat(src);
  if (st.isSymbolicLink() || !st.isFile()) {
    io.err('ledger setup: the gitleaks source is not a regular file');
    return 1;
  }
  if (st.size > MAX_BINARY_BYTES) {
    io.err('ledger setup: the gitleaks source is implausibly large');
    return 1;
  }
  const pins = JSON.parse(await readFile(new URL('../../../ops/gitleaks-pins.json', import.meta.url), 'utf8')) as { version?: unknown };
  if (typeof pins.version !== 'string' || !/^\d+\.\d+\.\d+$/.test(pins.version)) {
    io.err('ledger setup: ops/gitleaks-pins.json has no valid version');
    return 4;
  }
  const binDir = api.join(ledgerDir, '.hub', 'bin');
  await ensurePrivateDir(binDir, d.trust);
  const dst = api.join(binDir, d.platform === 'win32' ? 'gitleaks.exe' : 'gitleaks');
  const bytes = await readFile(src);
  // Same order as install.sh: drop the old copy and its side-cars, then place the new one.
  for (const f of [dst, `${dst}.sha256`, `${dst}.origin`]) await rm(f, { force: true });
  await writeAtomic(dst, bytes, 0o500, d.trust);
  const sha = createHash('sha256').update(bytes).digest('hex');
  await writeAtomic(`${dst}.sha256`, `${sha}\n`, 0o400, d.trust);
  await writeAtomic(
    `${dst}.origin`,
    `upstream v${pins.version} (sha256 verified against the in-repo pin ops/gitleaks-pins.json)\n`,
    0o400,
    d.trust,
  );
  io.out(JSON.stringify({ ok: true, path: dst, sha256: sha, version: pins.version }));
  return 0;
}

export async function cmdSetup(args: Args, io: Io, depsIn: Partial<SetupDeps> = {}): Promise<number> {
  const d: SetupDeps = {
    platform: process.platform,
    execPath: process.execPath,
    nodeVersion: process.versions.node,
    trust: {},
    homedir: () => os.homedir(),
    ...depsIn,
  };
  try {
    if (args.bools.has('platform-init')) return await platformInit(args, io, d);
    if (flag(args, 'private-dir') !== undefined) return await privateDirMode(args, io, d);
    if (flag(args, 'place-gitleaks') !== undefined) return await placeGitleaks(args, io, d);
    io.err('usage: ledger setup --platform-init | --private-dir <abs> | --place-gitleaks <exe> [--ledger-dir <abs>]');
    return 4;
  } catch (err) {
    if (err instanceof TrustError) {
      io.err(`ledger setup: refused (${err.code}): ${err.message}`);
      return 1;
    }
    if (err instanceof RangeError) {
      io.err(`ledger setup: ${err.message}`);
      return 4;
    }
    io.err(`ledger setup: ${err instanceof Error ? err.message : String(err)}`);
    return 1;
  }
}
